/**
 * @description : Bottom Navigation Bar for institute_user (mobile app)
 *                Renders tabs based on cds permission flags.
 * @author : Bala Krishna
 * @date   : 16-01-2023  (redesigned Aug-2026)
 */

import React, { useContext } from 'react';
import {
  FaTachometerAlt,
  FaUserCircle,
  FaBookOpen,
  FaPlus,
  FaEdit,
  FaTrash,
} from 'react-icons/fa';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';

const NavBar = ({ onOpenHomework }) => {
  const location = useLocation();
  const { stateAuth } = useContext(AuthContext);
  const cds = stateAuth?.user?.cds || '';

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="user-bottom-nav">

      {/* Dashboard – always visible */}
      <Link
        to="/dashboard"
        className={`user-bottom-nav-item${isActive('/dashboard') ? ' active' : ''}`}
      >
        <FaTachometerAlt className="user-bottom-nav-icon" />
        <span>Home</span>
      </Link>

      {/* My Profile — I_N_U_S */}
      {isExactMatch(cds, 'I_N_U_S') && (
        <Link
          to="/profile"
          className={`user-bottom-nav-item${isActive('/profile') ? ' active' : ''}`}
        >
          <FaUserCircle className="user-bottom-nav-icon" />
          <span>Profile</span>
        </Link>
      )}

      {/* Home Work — H_W_M */}
      {isExactMatch(cds, 'H_W_M') && (
        <button
          className="user-bottom-nav-item user-bottom-nav-btn"
          onClick={() => { navigate('/homework'); if (onOpenHomework) onOpenHomework(); }}
        >
          <FaBookOpen className="user-bottom-nav-icon" />
          <span>Homework</span>
        </button>
      )}

      {/* Homework — Create */}
      {isExactMatch(cds, 'H_W_M_C') && (
        <button
          className="user-bottom-nav-item user-bottom-nav-btn"
          onClick={() => onCreateHomework && onCreateHomework()}
        >
          <FaPlus className="user-bottom-nav-icon" />
          <span>Create Homework</span>
        </button>
      )}

      {/* Homework — Fetch */}
      {isExactMatch(cds, 'H_W_M_F') && (
        <button
          className="user-bottom-nav-item user-bottom-nav-btn"
          onClick={() => onFetchHomework && onFetchHomework()}
        >
          <FaBookOpen className="user-bottom-nav-icon" />
          <span>Fetch Homework</span>
        </button>
      )}

      {/* Homework — Update */}
      {isExactMatch(cds, 'H_W_M_U') && (
        <button
          className="user-bottom-nav-item user-bottom-nav-btn"
          onClick={() => onUpdateHomework && onUpdateHomework()}
        >
          <FaEdit className="user-bottom-nav-icon" />
          <span>Update Homework</span>
        </button>
      )}

      {/* Homework — Delete */}
      {isExactMatch(cds, 'H_W_M_D') && (
        <button
          className="user-bottom-nav-item user-bottom-nav-btn"
          onClick={() => onDeleteHomework && onDeleteHomework()}
        >
          <FaTrash className="user-bottom-nav-icon" />
          <span>Delete Homework</span>
        </button>
      )}


    </nav>
  );
};

export default NavBar;
